// ── محرك الذكاء الاصطناعي المحصّن للضغط العالي ─────────────────
// طابور تزامن (3 طلبات متوازية كحد أقصى لكل مستخدم) + إعادة محاولة
// بتراجع أُسّي عند الازدحام (429/5xx) + كاش للطلبات المتطابقة.
const AI_MAX_CONCURRENT = 3;
let _aiActive = 0; const _aiWait = [];
const _aiCache = new Map();
function _aiSlot(){ return new Promise(res=>{ if(_aiActive<AI_MAX_CONCURRENT){_aiActive++;res();} else _aiWait.push(res); }); }
function _aiFree(){ const n=_aiWait.shift(); if(n){ n(); } else { _aiActive=Math.max(0,_aiActive-1); } }
function _aiKey(sys,user,mt){ return mt+"|"+sys.length+"~"+user.length+"|"+sys.slice(0,60)+"|"+user.slice(0,120)+"|"+user.slice(-120); }

async function callAI(sys, user, mt = 1000) {
  const ck = _aiKey(sys,user,mt);
  if (_aiCache.has(ck)) return _aiCache.get(ck);
  await _aiSlot();
  try {
    let lastErr = null;
    for (let attempt = 0; attempt < 4; attempt++) {
      try {
        const r = await fetch(AI_ENDPOINT, {
          method:"POST", headers:{"Content-Type":"application/json"},
          body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:mt,system:sys,messages:[{role:"user",content:user}]})
        });
        if (r.status === 429 || r.status === 529 || r.status >= 500) {
          lastErr = new Error("الخدمة مزدحمة حالياً ("+r.status+") — أعدنا المحاولة تلقائياً");
        } else if (!r.ok) {
          throw new Error(`API ${r.status}`);
        } else {
          const d = await r.json();
          const txt = d.content?.map(b=>b.text||"").join("")||"";
          if (txt) {
            _aiCache.set(ck, txt);
            if (_aiCache.size > 40) _aiCache.delete(_aiCache.keys().next().value);
            return txt;
          }
          lastErr = new Error("استجابة فارغة");
        }
      } catch(e) {
        if (String(e.message||"").startsWith("API 4") && !String(e.message).includes("429")) throw e;
        lastErr = e;
      }
      // تراجع أُسّي مع عشوائية: 0.8ث ← 1.6 ← 3.2 (+jitter)
      await new Promise(res=>setTimeout(res, 800*Math.pow(2,attempt) + Math.random()*500));
    }
    throw lastErr || new Error("تعذّر الاتصال بعد عدة محاولات — الضغط مرتفع، حاول بعد لحظات");
  } finally { _aiFree(); }
}
async function callAIJson(sys, user, mt = 1000) {
  const t = await callAI(sys+"\nReply ONLY valid JSON no backticks.", user, mt);
  return JSON.parse(t.replace(/```json|```/g,"").trim());
}

// ── FILE READER ──────────────────────────────────────────────
async function readFile(file) {
  if (!file) return "";
  const name = file.name.toLowerCase();
  const size = (file.size/1024).toFixed(1);
  if (name.match(/\.(txt|md|csv|json|xml|html)$/)) {
    return new Promise(res=>{
      const r=new FileReader();
      r.onload=()=>res((r.result||"").slice(0,8000));
      r.onerror=()=>res(`[${file.name}]`);
      r.readAsText(file,"utf-8");
    });
  }
  if (name.endsWith(".pdf")) return await readPdfText(file, 16000);
  if (name.match(/\.(jpg|jpeg|png|gif|webp)$/)) {
    return new Promise(res=>{const r=new FileReader();r.onload=()=>res(`[صورة:${file.name}|${size}KB]`);r.onerror=()=>res(`[${file.name}]`);r.readAsDataURL(file);});
  }
  if (name.match(/\.(docx|pptx|xlsx)$/)) {
    // استخراج النص من ملفات Office (zip) — قراءة محتوى XML
    return new Promise(res=>{
      const r=new FileReader();
      r.onload=async()=>{
        try {
          const buf=new Uint8Array(r.result);
          const txt=await extractOfficeText(buf, name);
          res(txt && txt.length>20 ? txt.slice(0,12000) : `[${file.name}|${size}KB — تعذّر استخراج النص، جرّب نسخ المحتوى ولصقه]`);
        } catch(e){ res(`[${file.name}|${size}KB — تعذّر القراءة]`); }
      };
      r.onerror=()=>res(`[${file.name}]`);
      r.readAsArrayBuffer(file);
    });
  }
  return `[${file.name}|${size}KB|${file.type||"?"}]`;
}

// استخراج نص من ملفات Office (docx/pptx/xlsx) عبر فك ضغط zip وقراءة XML
async function extractOfficeText(bytes, name) {
  // فك ضغط ZIP يدوياً (للملفات غير المضغوطة DEFLATE نستخدم DecompressionStream)
  const files = unzipEntries(bytes);
  let xmlParts = [];
  const want = name.endsWith(".docx") ? ["word/document.xml"]
    : name.endsWith(".pptx") ? Object.keys(files).filter(k=>k.match(/ppt\/slides\/slide\d+\.xml/))
    : Object.keys(files).filter(k=>k.match(/xl\/(sharedStrings|worksheets\/sheet\d+)\.xml/));
  for (const w of want) {
    if (files[w]) {
      const xml = await inflateEntry(bytes, files[w]);
      if (xml) xmlParts.push(xml);
    }
  }
  // استخراج النص من وسوم <w:t>, <a:t>, <t>
  let text = xmlParts.join(" ")
    .replace(/<w:p[^>]*>/g,"\n").replace(/<a:p[^>]*>/g,"\n")
    .replace(/<[^>]+>/g," ")
    .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&#\d+;/g," ")
    .replace(/[ \t]+/g," ").replace(/\n{3,}/g,"\n\n").trim();
  return text;
}

// قراءة جدول ZIP المركزي واستخراج المدخلات
function unzipEntries(bytes) {
  const entries = {};
  // البحث عن End of Central Directory
  let eocd = -1;
  for (let i=bytes.length-22; i>=0; i--) {
    if (bytes[i]===0x50&&bytes[i+1]===0x4b&&bytes[i+2]===0x05&&bytes[i+3]===0x06) { eocd=i; break; }
  }
  if (eocd<0) return entries;
  const cdOffset = bytes[eocd+16]|(bytes[eocd+17]<<8)|(bytes[eocd+18]<<16)|(bytes[eocd+19]<<24);
  let p = cdOffset;
  while (p<bytes.length-4 && bytes[p]===0x50&&bytes[p+1]===0x4b&&bytes[p+2]===0x01&&bytes[p+3]===0x02) {
    const method = bytes[p+10]|(bytes[p+11]<<8);
    const compSize = bytes[p+20]|(bytes[p+21]<<8)|(bytes[p+22]<<16)|(bytes[p+23]<<24);
    const nameLen = bytes[p+28]|(bytes[p+29]<<8);
    const extraLen = bytes[p+30]|(bytes[p+31]<<8);
    const commLen = bytes[p+32]|(bytes[p+33]<<8);
    const lho = bytes[p+42]|(bytes[p+43]<<8)|(bytes[p+44]<<16)|(bytes[p+45]<<24);
    const fname = new TextDecoder().decode(bytes.slice(p+46, p+46+nameLen));
    entries[fname] = { method, compSize, lho };
    p += 46+nameLen+extraLen+commLen;
  }
  return entries;
}

// فك ضغط مدخل واحد (تخزين أو DEFLATE)
async function inflateEntry(bytes, entry) {
  return new Promise(async (resolve)=>{
    try {
      const lho = entry.lho;
      const b = bytes;
      const nameLen = b[lho+26]|(b[lho+27]<<8);
      const extraLen = b[lho+28]|(b[lho+29]<<8);
      const dataStart = lho+30+nameLen+extraLen;
      const comp = b.slice(dataStart, dataStart+entry.compSize);
      if (entry.method===0) { resolve(new TextDecoder().decode(comp)); return; }
      // DEFLATE عبر DecompressionStream
      if (typeof DecompressionStream!=="undefined") {
        const ds=new DecompressionStream("deflate-raw");
        const stream=new Response(comp).body.pipeThrough(ds);
        const txt=await new Response(stream).text();
        resolve(txt);
      } else resolve("");
    } catch { resolve(""); }
  });
}

