// ═══ قسم الأبحاث العربية المتخصص (مدمج) ═══
async function arAI(sys, user, mt = 1100) {
  const r = await fetch(AI_ENDPOINT, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: mt, system: sys, messages: [{ role: "user", content: user }] })
  });
  if (!r.ok) throw new Error(r.status);
  const d = await r.json();
  return d.content?.map(b => b.text || "").join("") || "";
}
async function arAIJ(sys, user, mt = 1100) {
  const t = await arAI(sys + "\nأجب بـ JSON صحيح فقط بلا backticks.", user, mt);
  return JSON.parse(t.replace(/```json|```/g, "").trim());
}

// ── FILE READER ──────────────────────────────────────────────
async function arReadF(file) {
  if (!file) return "";
  const name = file.name.toLowerCase();
  if (name.match(/\.(txt|md|csv|json|html)$/))
    return new Promise(res => { const r = new FileReader(); r.onload = () => res((r.result || "").slice(0, 12000)); r.onerror = () => res(""); r.readAsText(file, "utf-8"); });
  if (name.endsWith(".pdf"))
    return new Promise(res => {
      const r = new FileReader();
      r.onload = () => {
        const bytes = new Uint8Array(r.result); let t = "";
        for (let i=0;i<bytes.length-1;i++){ if(bytes[i]>=32&&bytes[i]<127)t+=String.fromCharCode(bytes[i]); else if(bytes[i]===10)t+=" "; }
        const m=t.match(/BT[\s\S]*?ET/g)||[];
        res(m.map(x=>x.replace(/BT|ET|\d+\.\d+|\/\w+/g," ").replace(/\s+/g," ").trim()).join(" ").slice(0,10000)||`[PDF: ${file.name}]`);
      };
      r.onerror=()=>res(`[${file.name}]`); r.readAsArrayBuffer(file);
    });
  return `[${file.name} | ${(file.size/1024).toFixed(1)}KB]`;
}

