const SEVDD = {"حرجة":"#ef4444","مهمة":"#f59e0b","طفيفة":"#3b82f6"};

// ════════════════════════════════════════════════════════════
function DeepDisciplineSystem({ T }) {
  const [disc, setDisc] = useState(null);
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);
  const [wpp, setWpp] = useState(400);
  const [loading, setLoading] = useState(false);
  const [prog, setProg] = useState("");
  const [pages, setPages] = useState([]);
  const [summary, setSummary] = useState(null);
  const [filter, setFilter] = useState("all");
  const fileRef = useRef();

  const run = async () => {
    const fcs = await Promise.all(files.map(ddRead));
    const all=[text,...fcs].join("\n").replace(/\s+/g," ").trim();
    if(!all){ alert("ارفع البحث أو الصق النص"); return; }
    setLoading(true); setPages([]); setSummary(null);
    const words=all.split(/\s+/);
    const chunks=[]; for(let i=0;i<words.length;i+=wpp) chunks.push(words.slice(i,i+wpp).join(" "));
    const n=Math.min(chunks.length,12);
    const checksAr=disc.checks.map((c,i)=>`${i+1}. ${c}`).join("\n");
    const res=[];
    for(let ci=0;ci<n;ci++){
      setProg(`المراجعة المتخصصة (${disc.ar}) — صفحة ${ci+1}/${n}`);
      try {
        const r=await ddAIJ(
          `${disc.sys}\nأنت تراجع صفحة من بحث في تخصص «${disc.ar}» مراجعة عميقة متخصصة. راجع هذا المقطع فقط ولا تخترع. كل ملاحظة تقتبس النص الحرفي. طبّق معايير الفحص الدقيقة لهذا التخصص حصراً:\n${checksAr}\nJSON فقط:
{"pageSummary":"ملخص دقيق لحالة الصفحة بلغة المتخصص","observations":[{"quote":"النص الحرفي المقتبس","check":"أي معيار تخصصي ينطبق","issue":"الخطأ الدقيق من منظور المتخصص","severity":"حرجة|مهمة|طفيفة","correction":"التصحيح الصحيح علمياً"}]}`,
          `بحث في ${disc.ar} — صفحة ${ci+1}:\n\n${chunks[ci].slice(0,2200)}`, 1900
        );
        res.push({page:ci+1, summary:r.pageSummary||"", observations:(r.observations||[]).filter(o=>o.quote)});
      } catch { res.push({page:ci+1,summary:"تعذّرت المراجعة",observations:[]}); }
      setPages([...res]);
    }
    // discipline-level summary
    setProg("إعداد الخلاصة المتخصصة...");
    const allObs=res.flatMap(p=>p.observations);
    try {
      const s=await ddAIJ(
        `${disc.sys}\nبناءً على ملاحظات المراجعة، أعطِ خلاصة متخصصة. JSON فقط:
{"overallScore":<0-100>,"verdict":"الحكم المتخصص","topIssues":["أخطر القضايا التخصصية"],"recommendation":"التوصية"}`,
        `تخصص: ${disc.ar} | عدد الملاحظات: ${allObs.length}\nأبرز الملاحظات: ${allObs.slice(0,15).map(o=>`[${o.severity}] ${o.issue}`).join(" | ")}`, 900
      );
      setSummary(s);
    } catch {}
    setProg(""); setLoading(false);
  };

  const allObs=pages.flatMap(p=>p.observations.map(o=>({...o,page:p.page})));
  const sevCount={"حرجة":0,"مهمة":0,"طفيفة":0}; allObs.forEach(o=>{if(sevCount[o.severity]!==undefined)sevCount[o.severity]++;});

  const buildReport = () => {
    const esc=s=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    let body=`<div class="cover"><h1>${disc.icon} تقرير المراجعة المتخصصة — ${disc.ar}</h1><p><b>${esc(title)}</b></p>
      <p>الملاحظات: ${allObs.length} | حرجة: ${sevCount["حرجة"]} | مهمة: ${sevCount["مهمة"]} | طفيفة: ${sevCount["طفيفة"]}</p>
      ${summary?`<p>التقييم: ${summary.overallScore}/100 — ${esc(summary.verdict||"")}</p>`:""}</div>`;
    if(summary?.topIssues?.length){ body+=`<h2>أخطر القضايا التخصصية</h2><ol>${summary.topIssues.map(t=>`<li>${esc(t)}</li>`).join("")}</ol>`; }
    pages.forEach(p=>{
      body+=`<div class="page"><h2>📄 صفحة ${p.page}</h2>`;
      if(p.summary) body+=`<div class="sm">${esc(p.summary)}</div>`;
      if(p.observations.length){ body+=`<ol>`; p.observations.forEach(o=>{ body+=`<li class="obs sev-${o.severity}"><span class="badge">${esc(o.check)} · ${o.severity}</span><div class="q">"${esc(o.quote)}"</div><p><b>الملاحظة:</b> ${esc(o.issue)}</p>${o.correction?`<p class="r"><b>التصحيح:</b> ${esc(o.correction)}</p>`:""}</li>`; }); body+=`</ol>`; }
      else body+=`<p class="clean">✓ لا ملاحظات تخصصية جوهرية</p>`;
      body+=`</div>`;
    });
    return `<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>تقرير ${esc(disc.ar)}</title>
<style>body{font-family:Arial;padding:40px;color:#1a2540;line-height:1.8}.cover{text-align:center;border-bottom:4px solid ${disc.color};padding-bottom:18px;margin-bottom:20px}.cover h1{color:${disc.color}}h2{color:${disc.color};font-size:15px;border-bottom:1px solid #ddd;padding-bottom:5px;margin-top:20px}.sm{background:#fef9f0;border-right:4px solid ${disc.color};padding:9px 12px;border-radius:7px;margin:8px 0;font-size:13px}.obs{margin-bottom:12px;border:1px solid #e5e7eb;border-radius:8px;padding:10px;list-style:none}.sev-حرجة{border-right:4px solid #ef4444}.sev-مهمة{border-right:4px solid #f59e0b}.sev-طفيفة{border-right:4px solid #3b82f6}.badge{display:inline-block;background:#eef2ff;color:#4338ca;font-size:11px;font-weight:700;padding:2px 9px;border-radius:12px;margin-bottom:6px}.q{background:#f8fafc;border-radius:6px;padding:7px 10px;font-style:italic;color:#475569;font-size:12px;margin-bottom:6px}.r{background:#ecfdf5;border-radius:6px;padding:6px 10px;color:#065f46}.clean{color:#16a34a}ol{padding-right:20px}</style></head><body>${body}</body></html>`;
  };
  const dl=(c,m,e)=>{const b=new Blob(["\uFEFF"+c],{type:m+";charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=`مراجعة_${disc.ar}_${title||""}.${e}`;a.click();URL.revokeObjectURL(u);};

  const shown = filter==="all"?pages:pages.map(p=>({...p,observations:p.observations.filter(o=>o.severity===filter)}));

  return <div dir="rtl" style={{fontFamily:"'Tajawal','Inter','Segoe UI',sans-serif",color:T.text,background:T.bg,minHeight:"100vh",padding:"20px 16px"}}>
    <div style={{maxWidth:1080,margin:"0 auto"}}>
      <div style={{textAlign:"center",marginBottom:18}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:8,padding:"6px 16px",background:T.violet+"15",border:`1px solid ${T.violet}44`,borderRadius:24,marginBottom:10}}>
          <span>🔬</span><span style={{fontSize:12,color:T.violet,fontWeight:700}}>مراجعة عميقة بمعايير كل تخصص · صفحة بصفحة · بالاقتباس</span>
        </div>
        <h1 style={{margin:"0 0 6px",fontSize:24,fontWeight:900,color:T.gold}}>🔬 المراجعة العميقة المتخصصة</h1>
        <p style={{margin:0,fontSize:13,color:T.textS}}>لكل تخصص معاييره الدقيقة وأخطاؤه التي يكشفها الخبير المتخصص</p>
      </div>

      {!disc && <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))",gap:11}}>
        {DD_DISC.map(d=><button key={d.id} onClick={()=>{setDisc(d);setPages([]);setSummary(null);}}
          style={{background:T.card,border:`1.5px solid ${T.border}`,borderRadius:14,padding:16,cursor:"pointer",fontFamily:"inherit",textAlign:"center",transition:"all .18s"}}
          onMouseEnter={e=>{e.currentTarget.style.borderColor=d.color;e.currentTarget.style.transform="translateY(-3px)";}}
          onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform="none";}}>
          <div style={{width:52,height:52,margin:"0 auto 10px",borderRadius:14,background:d.color+"1a",border:`1px solid ${d.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:26}}><EmIcon e={d.icon}/></div>
          <div style={{fontSize:13,fontWeight:800,color:T.text,marginBottom:4}}>{d.ar}</div>
          <DdTag ch={`${d.checks.length} معايير دقيقة`} color={d.color}/>
        </button>)}
      </div>}

      {disc && pages.length===0 && !loading && <div>
        <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:14}}>
          <DdBtn ch="← التخصصات" onClick={()=>setDisc(null)} v="ghost" size="sm" T={T}/>
          <div style={{width:44,height:44,borderRadius:12,background:disc.color+"1a",border:`1px solid ${disc.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}><EmIcon e={disc.icon}/></div>
          <h2 style={{margin:0,fontSize:18,fontWeight:900,color:T.text}}>{disc.ar}</h2>
        </div>
        <div style={{background:disc.color+"0d",border:`1px solid ${disc.color}33`,borderRadius:12,padding:13,marginBottom:14}}>
          <p style={{margin:"0 0 8px",fontSize:12,fontWeight:700,color:disc.color}}>🔍 معايير الفحص الدقيقة لهذا التخصص:</p>
          <div style={{display:"flex",flexDirection:"column",gap:5}}>{disc.checks.map((c,i)=><div key={i} style={{fontSize:12,color:T.text,display:"flex",gap:7}}><span style={{color:disc.color,fontWeight:900}}>{i+1}.</span>{c}</div>)}</div>
        </div>
        <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:16,boxShadow:T.shadow}}>
          <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="عنوان البحث" style={{width:"100%",padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none",marginBottom:12}}/>
          <div onClick={()=>fileRef.current?.click()} onDrop={e=>{e.preventDefault();setFiles(Array.from(e.dataTransfer.files).slice(0,3));}} onDragOver={e=>e.preventDefault()}
            style={{border:`2px dashed ${files.length?T.emerald:T.border}`,borderRadius:11,padding:"14px",textAlign:"center",cursor:"pointer",background:files.length?T.emerald+"08":T.bgS,marginBottom:11}}>
            <input ref={fileRef} type="file" multiple accept=".txt,.md,.pdf,.doc,.docx,.csv,.json,.rtf,.xlsx,.pptx" style={{display:"none"}} onChange={e=>setFiles(Array.from(e.target.files).slice(0,3))}/>
            {files.length?<p style={{margin:0,fontSize:12,color:T.emerald,fontWeight:700}}>✅ {files.map(f=>f.name).join("، ")}</p>:<p style={{margin:0,fontSize:12,color:T.textS}}>📎 ارفع البحث (Word · PDF) أو الصق النص</p>}
          </div>
          <textarea value={text} onChange={e=>setText(e.target.value)} placeholder="أو الصق نص البحث كاملاً..." rows={6} style={{width:"100%",padding:"11px 13px",borderRadius:10,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",marginBottom:11}}/>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
            <span style={{fontSize:12,color:T.textS,fontWeight:700}}>كلمات/صفحة:</span>
            <input type="number" value={wpp} onChange={e=>setWpp(parseInt(e.target.value)||400)} step="50" style={{width:85,padding:"7px 10px",borderRadius:8,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:12,fontFamily:"inherit",outline:"none"}}/>
          </div>
          <DdBtn ch={<><EmIcon e={disc.icon}/> ابدأ المراجعة المتخصصة العميقة</>} onClick={run} disabled={!text.trim()&&!files.length} full T={T} size="lg"/>
        </div>
      </div>}

      {loading && pages.length===0 && <div style={{background:T.card,border:`1px solid ${disc.color}44`,borderRadius:14,padding:36,textAlign:"center",boxShadow:T.shadow}}>
        <div style={{display:"flex",justifyContent:"center",marginBottom:12}}><DdSp c={disc.color}/></div><p style={{margin:0,fontSize:13,color:T.textS}}>{prog}</p>
      </div>}

      {pages.length>0 && <div>
        <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:14,flexWrap:"wrap"}}>
          <DdBtn ch="← جديد" onClick={()=>{setPages([]);setSummary(null);setDisc(null);}} v="ghost" size="sm" T={T}/>
          <DdTag ch={<><EmIcon e={disc.icon}/> {disc.ar}</>} color={disc.color}/>
          {title&&<span style={{fontSize:13,fontWeight:700,color:T.text}}>{title}</span>}
          <div style={{flex:1}}/>
          {!loading && <><DdBtn ch="📄 Word" onClick={()=>dl(buildReport(),"application/msword","doc")} v="gold" size="sm" T={T}/>
          <DdBtn ch="📕 PDF" onClick={()=>{const w=window.open();w.document.write(buildReport().replace("</body>","<script>window.onload=()=>window.print()<\/script></body>"));}} v="ghost" size="sm" T={T}/>
          <DdBtn ch="🖨️" onClick={()=>{const w=window.open();w.document.write(buildReport());w.print();}} v="ghost" size="sm" T={T}/></>}
        </div>

        {summary && <div style={{background:`linear-gradient(135deg,${disc.color}12,transparent)`,border:`1px solid ${disc.color}44`,borderRadius:13,padding:15,marginBottom:14,display:"flex",gap:14,alignItems:"center",flexWrap:"wrap"}}>
          <div style={{textAlign:"center"}}><div style={{fontSize:28,fontWeight:900,color:disc.color}}>{summary.overallScore??"—"}</div><div style={{fontSize:10,color:T.textD}}>/100</div></div>
          <p style={{flex:1,margin:0,fontSize:13,color:T.text,lineHeight:1.6,minWidth:180}}>{summary.verdict}</p>
        </div>}

        <div style={{display:"flex",gap:7,marginBottom:14,flexWrap:"wrap"}}>
          {[["all","الكل",allObs.length],["حرجة","حرجة",sevCount["حرجة"]],["مهمة","مهمة",sevCount["مهمة"]],["طفيفة","طفيفة",sevCount["طفيفة"]]].map(([f,l,n])=><button key={f} onClick={()=>setFilter(f)} style={{padding:"6px 13px",borderRadius:8,border:`1.5px solid ${filter===f?(SEVDD[f]||disc.color):T.border}`,background:filter===f?(SEVDD[f]||disc.color)+"18":T.card,color:filter===f?(SEVDD[f]||disc.color):T.textS,cursor:"pointer",fontFamily:"inherit",fontWeight:700,fontSize:11}}>{l} ({n})</button>)}
        </div>

        {loading && <div style={{textAlign:"center",padding:12,marginBottom:8}}><div style={{display:"inline-flex",alignItems:"center",gap:8,color:T.textS,fontSize:12}}><DdSp c={disc.color}/> {prog}</div></div>}

        {shown.map(p=><div key={p.page} style={{marginBottom:16,background:T.card,border:`1px solid ${T.border}`,borderRadius:14,overflow:"hidden",boxShadow:T.shadow}}>
          <div style={{display:"flex",alignItems:"center",gap:11,padding:"12px 15px",background:`linear-gradient(90deg,${disc.color}12,transparent)`,borderBottom:`1px solid ${T.border}`}}>
            <div style={{width:38,height:38,borderRadius:10,background:disc.color+"1a",border:`1px solid ${disc.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:15,fontWeight:900,color:disc.color}}>{p.page}</div>
            <div style={{flex:1}}>
              <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:2}}><h3 style={{margin:0,fontSize:14,fontWeight:800,color:T.text}}>صفحة {p.page}</h3>{p.observations.length>0?<DdTag ch={`${p.observations.length}`} color={disc.color}/>:<DdTag ch="سليمة" color={T.emerald}/>}</div>
              {p.summary&&<p style={{margin:0,fontSize:12,color:T.textS,lineHeight:1.5}}>{p.summary}</p>}
            </div>
          </div>
          <div style={{padding:"6px 15px 12px"}}>
            {p.observations.length===0?<p style={{margin:"8px 0",fontSize:12,color:T.emerald}}>✓ لا ملاحظات تخصصية جوهرية</p>
            :p.observations.map((o,i)=><div key={i} style={{padding:"10px",marginTop:8,background:T.bgS,border:`1px solid ${T.border}`,borderRight:`4px solid ${SEVDD[o.severity]||T.textD}`,borderRadius:9}}>
              <div style={{display:"flex",gap:6,marginBottom:6,flexWrap:"wrap",alignItems:"center"}}>
                <span style={{fontSize:11,fontWeight:900,color:T.textD}}>{i+1}.</span>
                <DdTag ch={o.check} color={disc.color}/><DdTag ch={o.severity} color={SEVDD[o.severity]||T.textD}/>
              </div>
              {o.quote&&<div style={{background:T.bg,border:`1px solid ${T.border}`,borderRadius:7,padding:"6px 10px",marginBottom:6,fontSize:12,color:T.textS,fontStyle:"italic"}}>"{o.quote}"</div>}
              <p style={{margin:"0 0 5px",fontSize:13,color:T.text,fontWeight:600,lineHeight:1.6}}>⚠️ {o.issue}</p>
              {o.correction&&<div style={{background:T.emerald+"12",borderRadius:7,padding:"6px 10px"}}><span style={{fontSize:11,fontWeight:700,color:T.emerald}}>✅ التصحيح: </span><span style={{fontSize:12,color:T.text}}>{o.correction}</span></div>}
            </div>)}
          </div>
        </div>)}
      </div>}
    </div>
    <style>{`*{box-sizing:border-box}@keyframes spin{to{transform:rotate(360deg)}}::-webkit-scrollbar{width:5px;height:5px}::-webkit-scrollbar-thumb{background:${T.border};border-radius:3px}`}</style>
  </div>;
}


