// ── StdTool: المكوّن القياسي لأدوات المعالجة النصية ──
function StdTool({ toolKey, T }) {
  const cfg = TC[toolKey] || { s:"أنت مساعد خبير. حلّل المحتوى التالي وقدّم ملاحظات مفصّلة.", lbl:"الأداة", ph:"الصق النص أو ارفع الملف...", btn:"تشغيل" };
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState("");
  const [copied, setCopied] = useState(false);

  const run = async () => {
    const fcs = await Promise.all(files.map(readFile));
    const src = [text, ...fcs].join("\n").trim();
    if (!src) { alert("ارفع الملف أو الصق النص أولاً"); return; }
    setLoading(true); setResult("");
    try { setResult(await callAI(cfg.s, src, 1600)); }
    catch(e){ setResult("تعذّر: "+e.message); }
    finally { setLoading(false); }
  };
  const dl=(c,m,e)=>{const b=new Blob(["\uFEFF"+c],{type:m+";charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=`${cfg.lbl}.${e}`;a.click();URL.revokeObjectURL(u);};

  return <div>
    <FileZone files={files} setFiles={setFiles} T={T}/>
    <textarea value={text} onChange={e=>setText(e.target.value)} placeholder={cfg.ph} rows={6}
      style={{width:"100%",padding:"11px 13px",borderRadius:10,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",margin:"11px 0"}}/>
    <Btn ch={loading?<><Spin/> جاري المعالجة...</>:`✨ ${cfg.btn}`} onClick={run} disabled={loading} full T={T}/>
    {result && <Card T={T} style={{marginTop:14}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
        <h4 style={{margin:0,fontSize:14,fontWeight:800,color:T.gold}}>📄 النتيجة</h4>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          <Btn ch={copied?"✅":"📋 نسخ"} onClick={()=>{navigator.clipboard.writeText(result);setCopied(true);setTimeout(()=>setCopied(false),2000);}} v="ghost" size="xs" T={T}/>
          <Btn ch="📄 Word" onClick={()=>dl(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"></head><body style="font-family:Arial;line-height:1.9;white-space:pre-wrap">${result.replace(/</g,"&lt;")}</body></html>`,"application/msword","doc")} v="ghost" size="xs" T={T}/>
          <Btn ch="⬇️ نص" onClick={()=>dl(result,"text/plain","txt")} v="ghost" size="xs" T={T}/>
          <Btn ch="🖨️" onClick={()=>{const w=window.open();w.document.write(`<html dir="rtl"><head><meta charset="utf-8"></head><body style="font-family:Arial;line-height:1.9;white-space:pre-wrap;padding:40px">${result.replace(/</g,"&lt;")}</body></html>`);w.print();}} v="ghost" size="xs" T={T}/>
        </div>
      </div>
      <pre style={{margin:0,fontSize:13,color:T.text,lineHeight:1.9,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{result}</pre>
    </Card>}
  </div>;
}


// ═══ مركز المراجعة التلقائي الموحّد ═══
function AutoReviewCenter({ T }) {
  const [title, setTitle] = useState("");
  const [field, setField] = useState("");
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);
  const [running, setRunning] = useState(false);
  const [prog, setProg] = useState("");
  const [done, setDone] = useState(0);
  const [results, setResults] = useState({});
  const [overview, setOverview] = useState("");
  const [pubReport, setPubReport] = useState(null);
  const fileRef = useRef();

  // محركات المراجعة الشاملة (تعمل تلقائياً على المصدر)
  const ENGINES = [
    { key:"lang", icon:"📝", ar:"التدقيق اللغوي والصياغة", sys:"أنت مدقق لغوي خبير. راجع النص: الأخطاء النحوية والإملائية والترقيم والركاكة والأسلوب. اذكر أبرز الأخطاء بالاقتباس مع التصحيح." },
    { key:"ai", icon:"🤖", ar:"كشف الذكاء الاصطناعي", sys:"أنت كاشف للكتابة بالذكاء الاصطناعي. حلّل المؤشرات (العبارات النمطية، العمومية، التكرار، القفزات المنطقية) وأعطِ نسبة اشتباه مع الأدلة بالاقتباس." },
    { key:"method", icon:"🔬", ar:"التدقيق المنهجي", sys:"أنت خبير مناهج البحث. دقّق المنهجية: التوافق بين السؤال والمنهج والأداة، العينة، الإجراءات، الأخطاء المنهجية. بالاقتباس." },
    { key:"stat", icon:"📊", ar:"التحقق الإحصائي", sys:"أنت خبير إحصاء. دقّق التحليل الإحصائي: ملاءمة الاختبارات، المعادلات، حجم العينة، صحة النتائج وتفسيرها، الاتساق الداخلي للأرقام. بالاقتباس." },
    { key:"refs", icon:"🔖", ar:"تدقيق المراجع", sys:"أنت مدقق مراجع. افحص المراجع والاستشهادات: الاكتمال، المراجع الوهمية المحتملة، تطابق الاستشهاد الداخلي مع القائمة، المراجع غير المستخدمة. بالاقتباس." },
    { key:"plag", icon:"📑", ar:"كشف الانتحال", sys:"أنت خبير كشف الانتحال (مباشر/غير مباشر/ذاتي/هيكلي). اكشف مؤشرات الاقتباس غير الموثّق وإعادة الصياغة المبالغة. بالاقتباس." },
    { key:"halluc", icon:"👻", ar:"كشف الهلوسة العلمية", sys:"أنت خبير كشف الهلوسة العلمية. اكشف النظريات والإحصاءات والاقتباسات الوهمية والمصطلحات المختلقة. بالاقتباس." },
    { key:"content", icon:"📚", ar:"التقييم العلمي للمحتوى", sys:"أنت محكّم أكاديمي. قيّم المحتوى العلمي: الأصالة، الفجوة البحثية، الإطار النظري، المناقشة، الاستنتاجات، التوصيات. بالاقتباس." },
    { key:"struct", icon:"🧭", ar:"الاتساق والبناء", sys:"أنت محكّم خبير. افحص الاتساق الداخلي: توافق العنوان مع المشكلة مع الأهداف مع الأسئلة مع النتائج مع التوصيات، والترابط المنطقي. بالاقتباس." },
  ];

  const handleFile = (fs) => { setFiles(Array.from(fs).slice(0,3)); };

  const runAuto = async () => {
    const fcs = await Promise.all(files.map(readFile));
    const src = [text, ...fcs].join("\n").trim();
    if (!src) { alert("ارفع الملف أو الصق النص أولاً"); return; }
    setRunning(true); setResults({}); setOverview(""); setDone(0);
    const out = {};
    for (let i=0; i<ENGINES.length; i++) {
      const e = ENGINES[i];
      setProg(`${e.icon} ${e.ar} (${i+1}/${ENGINES.length})`);
      try {
        out[e.key] = await callAI(
          `${e.sys}\nراجع النص الفعلي فقط ولا تخترع. كن موجزاً ومركّزاً على أهم الملاحظات.`,
          `${title?("العنوان: "+title+"\n"):""}${field?("التخصص: "+field+"\n\n"):""}النص:\n${src.slice(0,9000)}`, 1100
        );
      } catch(err) { out[e.key] = "تعذّر: "+err.message; }
      setResults({...out}); setDone(i+1);
    }
    // الخلاصة التنفيذية الموحّدة
    setProg("📋 إعداد الخلاصة التنفيذية الموحّدة...");
    try {
      const combined = ENGINES.map(e=>`【${e.ar}】\n${out[e.key]||""}`).join("\n\n").slice(0,11000);
      setOverview(await callAI(
        "أنت رئيس لجنة تحكيم. بناءً على تقارير المحكّمين، اكتب خلاصة تنفيذية موحّدة: التقييم العام، أبرز نقاط القوة، أخطر الملاحظات (مرتّبة)، القرار والتوصية النهائية، ودرجة تقديرية من 100.",
        combined, 1500
      ));
    } catch(err) { setOverview("تعذّرت الخلاصة: "+err.message); }
    setProg(""); setRunning(false);
  };

  // التقرير الشامل الموحّد
  const buildReport = () => {
    const esc=s=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    let body=`<div class="cover"><h1>التقرير الشامل الموحّد للمراجعة</h1><p><b>${esc(title)||"مستند"}</b></p><p>${esc(field)||""} | ${new Date().toLocaleDateString("ar-SA")}</p></div>`;
    if(overview) body+=`<div class="exec"><h2>📋 الخلاصة التنفيذية</h2><div class="pre">${esc(overview)}</div></div>`;
    ENGINES.forEach(e=>{ if(results[e.key]) body+=`<div class="sec"><h2>${e.icon} ${e.ar}</h2><div class="pre">${esc(results[e.key])}</div></div>`; });
    return `<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>التقرير الشامل</title>
<style>body{font-family:Arial;padding:40px;color:#1a2540;line-height:1.9}.cover{text-align:center;border-bottom:4px solid #b45309;padding-bottom:18px;margin-bottom:22px}.cover h1{color:#b45309}.exec{background:#fef9f0;border:2px solid #d4a017;border-radius:10px;padding:16px;margin-bottom:20px}h2{color:#1f3864;font-size:16px;border-right:4px solid #b45309;padding-right:10px;margin-top:18px}.pre{white-space:pre-wrap;font-size:13px}.sec{margin-bottom:16px;page-break-inside:avoid}</style></head><body>${body}</body></html>`;
  };
  const buildMD = () => {
    let m=`# التقرير الشامل الموحّد\n\n**${title||"مستند"}** | ${field||""}\n\n`;
    if(overview) m+=`## 📋 الخلاصة التنفيذية\n\n${overview}\n\n---\n`;
    ENGINES.forEach(e=>{ if(results[e.key]) m+=`\n## ${e.icon} ${e.ar}\n\n${results[e.key]}\n`; });
    return m;
  };
  const buildTxt = () => {
    let t=`التقرير الشامل الموحّد\n${title||"مستند"} | ${field||""}\n${"=".repeat(45)}\n`;
    if(overview) t+=`\n📋 الخلاصة التنفيذية\n${overview}\n${"-".repeat(45)}\n`;
    ENGINES.forEach(e=>{ if(results[e.key]) t+=`\n${e.icon} ${e.ar}\n${results[e.key]}\n`; });
    return t;
  };
  const dl=(c,m,e)=>{const b=new Blob(["\uFEFF"+c],{type:m+";charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=`التقرير_الشامل_${title||"مراجعة"}.${e}`;a.click();URL.revokeObjectURL(u);};

  const hasResults = Object.keys(results).length>0;

  return <div>
    {!hasResults && !running && <div>
      <Card T={T} style={{marginBottom:14,background:`linear-gradient(135deg,${T.gold}10,transparent)`,border:`1px solid ${T.gold}44`}}>
        <h2 style={{margin:"0 0 6px",fontSize:20,fontWeight:900,color:T.gold}}>⚡ المراجعة التلقائية الشاملة</h2>
        <p style={{margin:0,fontSize:13,color:T.textS,lineHeight:1.7}}>ارفع الملف مرة واحدة → تعمل {ENGINES.length} محرّكات مراجعة تلقائياً (لغوي · ذكاء اصطناعي · منهجي · إحصائي · مراجع · انتحال · هلوسة · محتوى · اتساق) → تقرير شامل موحّد بكل الصيغ.</p>
      </Card>
      <Card T={T} style={{marginBottom:14}}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:12}}>
          <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="عنوان العمل" style={{padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
          <input value={field} onChange={e=>setField(e.target.value)} placeholder="التخصص" style={{padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
        </div>
        <FileZone files={files} setFiles={setFiles} T={T}/>
        <textarea value={text} onChange={e=>setText(e.target.value)} placeholder="أو الصق النص كاملاً..." rows={6} style={{width:"100%",padding:"11px 13px",borderRadius:10,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",margin:"12px 0"}}/>
        <Btn ch="⚡ ابدأ المراجعة التلقائية الشاملة" onClick={runAuto} disabled={!text.trim()&&!files.length} full T={T} size="lg"/>
      </Card>
    </div>}

    {running && <Card T={T} style={{textAlign:"center",padding:30,marginBottom:14}}>
      <div style={{display:"flex",justifyContent:"center",marginBottom:14}}><Spin color={T.gold}/></div>
      <p style={{margin:"0 0 12px",fontSize:14,fontWeight:700,color:T.text}}>{prog}</p>
      <div style={{height:8,background:T.bgS,borderRadius:4,overflow:"hidden",maxWidth:400,margin:"0 auto"}}>
        <div style={{height:"100%",width:`${done/ENGINES.length*100}%`,background:T.goldG,borderRadius:4,transition:"width .3s"}}/>
      </div>
      <p style={{margin:"8px 0 0",fontSize:12,color:T.textD}}>{done} / {ENGINES.length}</p>
    </Card>}

    {hasResults && <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,flexWrap:"wrap"}}>
        {!running && <Btn ch="← مراجعة جديدة" onClick={()=>{setResults({});setOverview("");setText("");setFiles([]);}} v="ghost" size="sm" T={T}/>}
        {title&&<span style={{fontSize:14,fontWeight:700,color:T.text}}>{title}</span>}
        <div style={{flex:1}}/>
        {!running && <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          <Btn ch="📄 Word" onClick={()=>dl(buildReport(),"application/msword","doc")} v="gold" size="sm" T={T}/>
          <Btn ch="📕 PDF" onClick={()=>{const w=window.open();w.document.write(buildReport().replace("</body>","<script>window.onload=()=>window.print()<\/script></body>"));}} v="ghost" size="sm" T={T}/>
          <Btn ch="🌐 HTML" onClick={()=>dl(buildReport(),"text/html","html")} v="ghost" size="sm" T={T}/>
          <Btn ch="📝 MD" onClick={()=>dl(buildMD(),"text/markdown","md")} v="ghost" size="sm" T={T}/>
          <Btn ch="📃 نص" onClick={()=>dl(buildTxt(),"text/plain","txt")} v="ghost" size="sm" T={T}/>
          <Btn ch="🖨️" onClick={()=>{const w=window.open();w.document.write(buildReport());w.print();}} v="ghost" size="sm" T={T}/>
        </div>}
      </div>

      {overview && <Card T={T} glow={T.gold} style={{marginBottom:14}}>
        <h3 style={{margin:"0 0 10px",fontSize:16,fontWeight:800,color:T.gold}}>📋 الخلاصة التنفيذية الموحّدة</h3>
        <pre style={{margin:0,fontSize:13,color:T.text,lineHeight:1.9,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{overview}</pre>
      </Card>}

      {ENGINES.map(e=> results[e.key] && <Card key={e.key} T={T} style={{marginBottom:12}}>
        <h4 style={{margin:"0 0 8px",fontSize:14,fontWeight:800,color:T.text,display:"flex",alignItems:"center",gap:7}}>
          <span style={{fontSize:18}}><EmIcon e={e.icon}/></span> {e.ar}
        </h4>
        <pre style={{margin:0,fontSize:12.5,color:T.text,lineHeight:1.85,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{results[e.key]}</pre>
      </Card>)}

      {running && <Card T={T} style={{textAlign:"center",padding:16}}><div style={{display:"inline-flex",alignItems:"center",gap:8,color:T.textS,fontSize:12}}><Spin color={T.gold}/> {prog}</div></Card>}
    </div>}
  </div>;
}



// ═══ مركز تحويل البحث إلى مخرجات بصرية (ResearchViz) ═══
function ResearchVizSystem({ T }) {
  const [vizType, setVizType] = useState(null);
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [prog, setProg] = useState("");
  const [output, setOutput] = useState(null);
  const fileRef = useRef();

  const VIZ = [
    { id:"poster", icon:"🖼️", ar:"ملصق علمي (Abstract Poster)", color:"#047857", kind:"html",
      sys:"أنت مصمم ملصقات علمية أكاديمية. حوّل البحث إلى ملصق علمي احترافي بصيغة HTML كاملة (RTL عربي) بأقسام: العنوان، المؤلفون، المقدمة، المنهجية، النتائج، الخلاصة، المراجع. استخدم تصميماً أكاديمياً أنيقاً بألوان متناسقة وأعمدة. أعطِ HTML فقط جاهزاً للعرض." },
    { id:"slides", icon:"📊", ar:"شرائح عرض (Slides)", color:"#1d4ed8", kind:"html",
      sys:"أنت مصمم عروض تقديمية. حوّل البحث إلى عرض شرائح بصيغة HTML (كل شريحة في div.slide بصفحة كاملة، RTL عربي): شريحة العنوان، المقدمة، المشكلة، المنهجية، النتائج، الخلاصة، التوصيات. تصميم احترافي مع ألوان وتباين. أعطِ HTML فقط." },
    { id:"infographic", icon:"📈", ar:"إنفوجرافيك (Infographic)", color:"#b45309", kind:"html",
      sys:"أنت مصمم إنفوجرافيك. حوّل البحث إلى إنفوجرافيك عمودي بصيغة HTML (RTL عربي) بأرقام بارزة، أيقونات نصية، إحصاءات، تدفق بصري. تصميم جذاب ملوّن. أعطِ HTML فقط." },
    { id:"graphical", icon:"🎨", ar:"ملخص بياني (Graphical Abstract)", color:"#0e7490", kind:"html",
      sys:"أنت مصمم Graphical Abstract. حوّل البحث إلى ملخص بياني أفقي بصيغة HTML (RTL) يوضّح: المدخلات ← الطريقة ← النتائج بتدفق بصري وصناديق ملوّنة وأسهم. أعطِ HTML فقط." },
    { id:"summary", icon:"📄", ar:"ملخص بحثي (Research Summary)", color:"#6d28d9", kind:"text",
      sys:"أنت كاتب ملخصات بحثية. لخّص البحث في ملخص تنفيذي منظّم (عربي): الهدف، المنهج، أبرز النتائج بالأرقام، الخلاصة، الكلمات المفتاحية. واضح ومركّز." },
    { id:"mermaid", icon:"🔀", ar:"مخطط Mermaid", color:"#be123c", kind:"mermaid",
      sys:"أنت خبير مخططات Mermaid. حوّل بنية/منهجية/تدفق البحث إلى كود Mermaid صحيح (flowchart TD أو graph). استخدم تسميات عربية. أعطِ كود Mermaid فقط بلا شرح وبلا backticks، يبدأ بـ flowchart TD." },
    { id:"mindmap", icon:"🧠", ar:"خريطة ذهنية (Mindmap)", color:"#0891b2", kind:"mermaid",
      sys:"أنت خبير الخرائط الذهنية. حوّل البحث إلى خريطة ذهنية بصيغة Mermaid mindmap. الجذر = موضوع البحث، الفروع = الأقسام الرئيسية وتفرعاتها. تسميات عربية. أعطِ كود mindmap فقط بلا backticks، يبدأ بـ mindmap." },
    { id:"diagram", icon:"📐", ar:"مخطط مفاهيمي (Diagram)", color:"#7c3aed", kind:"mermaid",
      sys:"أنت خبير المخططات المفاهيمية. حوّل العلاقات والمفاهيم في البحث إلى مخطط Mermaid (graph LR أو flowchart). أظهر العلاقات بين المتغيرات/المفاهيم. تسميات عربية. أعطِ كود Mermaid فقط بلا backticks." },
  ];

  const run = async () => {
    const fcs = await Promise.all(files.map(readFile));
    const src = [text, ...fcs].join("\n").trim();
    if (!src) { alert("ارفع البحث أو الصق النص أولاً"); return; }
    setLoading(true); setOutput(null); setProg(`توليد ${vizType.ar}...`);
    try {
      const raw = await callAI(
        `${vizType.sys}\nاعمل على المحتوى الفعلي المعطى فقط.`,
        `${title?("العنوان: "+title+"\n\n"):""}المحتوى:\n${src.slice(0,11000)}`, 3000
      );
      let content = raw.replace(/```html|```mermaid|```/g,"").trim();
      setOutput({ kind: vizType.kind, content });
    } catch(e){ alert("تعذّر: "+e.message); }
    finally { setLoading(false); setProg(""); }
  };

  // Mermaid live render via mermaid.ink (image) — works offline-safe by encoding
  const mermaidUrl = (code) => {
    try { return "https://mermaid.ink/svg/" + btoa(unescape(encodeURIComponent(JSON.stringify({code, mermaid:{theme:"default"}})))); }
    catch { return ""; }
  };

  const dl=(c,m,e)=>{const b=new Blob(["\uFEFF"+c],{type:m+";charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=`${vizType.ar}_${title||"viz"}.${e}`;a.click();URL.revokeObjectURL(u);};

  return <div>
    {!vizType && <div>
      <Card T={T} style={{marginBottom:14,background:`linear-gradient(135deg,${T.emerald}10,transparent)`,border:`1px solid ${T.emerald}44`}}>
        <h2 style={{margin:"0 0 6px",fontSize:20,fontWeight:900,color:T.emerald}}>🎨 حوّل بحثك إلى مخرجات بصرية</h2>
        <p style={{margin:0,fontSize:13,color:T.textS,lineHeight:1.7}}>ارفع البحث أو الصق النص → اختر نوع المخرج البصري → احصل على ملصق · شرائح · إنفوجرافيك · Mermaid · خريطة ذهنية · مخطط — جاهز للعرض والتحميل.</p>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(230px,1fr))",gap:11}}>
        {VIZ.map(v=><button key={v.id} onClick={()=>{setVizType(v);setOutput(null);}}
          style={{background:T.card,border:`1.5px solid ${T.border}`,borderRadius:14,padding:15,cursor:"pointer",fontFamily:"inherit",textAlign:"right",display:"flex",alignItems:"center",gap:11,transition:"all .18s"}}
          onMouseEnter={e=>{e.currentTarget.style.borderColor=v.color;e.currentTarget.style.transform="translateY(-2px)";}}
          onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform="none";}}>
          <div style={{width:46,height:46,borderRadius:12,background:v.color+"1a",border:`1px solid ${v.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}><EmIcon e={v.icon}/></div>
          <span style={{fontSize:13,fontWeight:700,color:T.text}}>{v.ar}</span>
        </button>)}
      </div>
    </div>}

    {vizType && !output && !loading && <div>
      <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:16}}>
        <Btn ch="← الأنواع" onClick={()=>setVizType(null)} v="ghost" size="sm" T={T}/>
        <div style={{width:44,height:44,borderRadius:12,background:vizType.color+"1a",border:`1px solid ${vizType.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}><EmIcon e={vizType.icon}/></div>
        <h2 style={{margin:0,fontSize:18,fontWeight:900,color:T.text}}>{vizType.ar}</h2>
      </div>
      <Card T={T}>
        <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="عنوان البحث" style={{width:"100%",padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none",marginBottom:12}}/>
        <FileZone files={files} setFiles={setFiles} T={T}/>
        <textarea value={text} onChange={e=>setText(e.target.value)} placeholder="أو الصق نص البحث/الملخص هنا..." rows={6} style={{width:"100%",padding:"11px 13px",borderRadius:10,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",margin:"12px 0"}}/>
        <Btn ch={<><EmIcon e={vizType.icon}/> توليد {vizType.ar}</>} onClick={run} disabled={!text.trim()&&!files.length} full T={T} size="lg"/>
      </Card>
    </div>}

    {loading && <Card T={T} style={{textAlign:"center",padding:36}}>
      <div style={{display:"flex",justifyContent:"center",marginBottom:12}}><Spin color={vizType.color}/></div>
      <p style={{margin:0,fontSize:13,color:T.textS}}>{prog}</p>
    </Card>}

    {output && <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,flexWrap:"wrap"}}>
        <Btn ch="← جديد" onClick={()=>setOutput(null)} v="ghost" size="sm" T={T}/>
        <Tag ch={vizType.ar} color={vizType.color}/>
        <div style={{flex:1}}/>
        {output.kind==="html" && <>
          <Btn ch="🌐 HTML" onClick={()=>dl(output.content,"text/html","html")} v="gold" size="sm" T={T}/>
          <Btn ch="📕 PDF" onClick={()=>{const w=window.open();w.document.write(output.content.replace("</body>","<script>window.onload=()=>window.print()<\/script></body>"));}} v="ghost" size="sm" T={T}/>
          <Btn ch="🖨️" onClick={()=>{const w=window.open();w.document.write(output.content);w.print();}} v="ghost" size="sm" T={T}/>
        </>}
        {output.kind==="mermaid" && <>
          <Btn ch="📋 نسخ الكود" onClick={()=>navigator.clipboard.writeText(output.content)} v="gold" size="sm" T={T}/>
          <Btn ch="⬇️ mmd" onClick={()=>dl(output.content,"text/plain","mmd")} v="ghost" size="sm" T={T}/>
        </>}
        {output.kind==="text" && <>
          <Btn ch="📄 Word" onClick={()=>dl(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"></head><body style="font-family:Arial;line-height:1.9;white-space:pre-wrap">${output.content.replace(/</g,"&lt;")}</body></html>`,"application/msword","doc")} v="gold" size="sm" T={T}/>
          <Btn ch="📋 نسخ" onClick={()=>navigator.clipboard.writeText(output.content)} v="ghost" size="sm" T={T}/>
        </>}
      </div>

      {output.kind==="html" && <Card T={T} style={{padding:0,overflow:"hidden"}}>
        <iframe srcDoc={output.content} title="viz" style={{width:"100%",height:600,border:"none",background:"#fff"}}/>
      </Card>}

      {output.kind==="mermaid" && <div>
        <Card T={T} style={{marginBottom:12,textAlign:"center",background:"#fff"}}>
          <img src={mermaidUrl(output.content)} alt="mermaid" style={{maxWidth:"100%",borderRadius:8}} onError={e=>{e.target.style.display="none";e.target.nextSibling.style.display="block";}}/>
          <p style={{display:"none",fontSize:12,color:T.textD,padding:20}}>للعرض: انسخ الكود والصقه في mermaid.live</p>
        </Card>
        <Card T={T}>
          <h4 style={{margin:"0 0 8px",fontSize:13,fontWeight:800,color:T.text}}>كود Mermaid</h4>
          <pre style={{margin:0,fontSize:12,color:T.text,lineHeight:1.7,whiteSpace:"pre-wrap",fontFamily:"monospace",background:T.bgS,padding:12,borderRadius:8,overflowX:"auto"}}>{output.content}</pre>
        </Card>
      </div>}

      {output.kind==="text" && <Card T={T}>
        <pre style={{margin:0,fontSize:13,color:T.text,lineHeight:1.9,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{output.content}</pre>
      </Card>}
    </div>}
  </div>;
}



// ═══ إطار تفسير النتائج الإحصائية والاستنتاجات (مدمج) ═══
function StatsInterpretSystem({ T }) {
  const [mode, setMode] = useState(null); // table | figure | hypotheses | full
  const [title, setTitle] = useState("");
  const [field, setField] = useState("");
  const [objectives, setObjectives] = useState("");
  const [hypotheses, setHypotheses] = useState("");
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [prog, setProg] = useState("");
  const [result, setResult] = useState(null);
  const fileRef = useRef();

  const MODES = [
    { id:"table", icon:"📋", ar:"تفسير الجداول الإحصائية", color:"#0369a1",
      desc:"لكل جدول: تفسير إحصائي وعلمي وقرار فرضية وحجم أثر",
      sys:"أنت خبير إحصائي ومحكّم أكاديمي. فسّر كل جدول إحصائي في النص تفسيراً منهجياً كاملاً. لكل جدول قدّم: التفسير الإحصائي (شرح الأرقام)، التفسير العلمي (ماذا تعني)، قرار الفرضية (قبول/رفض H0 عند α=0.05)، ربط الهدف (أي هدف تحقق)، المقارنة بالدراسات السابقة، حجم الأثر (Effect Size)، الأهمية العملية، الاستنتاج، التوصية، القرار النهائي.",
      schema:'{"items":[{"tableName":"اسم/رقم الجدول","statInterp":"التفسير الإحصائي","sciInterp":"التفسير العلمي","hypothesisDecision":"قرار الفرضية (قبول/رفض H0)","objectiveLink":"ربط الهدف","priorComparison":"المقارنة بالدراسات السابقة","effectSize":"حجم الأثر","practicalSig":"الأهمية العملية","conclusion":"الاستنتاج","recommendation":"التوصية"}],"summary":"خلاصة عامة"}' },
    { id:"figure", icon:"📈", ar:"تفسير الأشكال والرسوم", color:"#047857",
      desc:"الاتجاهات · القيم الشاذة · التغيرات الزمنية · الفروق",
      sys:"أنت خبير تحليل بصري للبيانات. فسّر كل شكل/رسم بياني في النص: تحليل الاتجاهات (Trend)، القيم الشاذة (Outliers)، التغيرات الزمنية، الفروق بين المجموعات، تقييم جودة النموذج الإحصائي. اربط التفسير البصري بالأرقام.",
      schema:'{"items":[{"figureName":"اسم/رقم الشكل","trend":"تحليل الاتجاه","outliers":"القيم الشاذة","temporal":"التغيرات الزمنية","groupDiff":"الفروق بين المجموعات","modelQuality":"تقييم جودة النموذج","interpretation":"التفسير العام"}],"summary":"خلاصة"}' },
    { id:"hypotheses", icon:"🧪", ar:"اختبار الفرضيات واتخاذ القرار", color:"#be123c",
      desc:"قرار كل فرضية مع P والأثر وفترة الثقة",
      sys:"أنت خبير اختبار الفرضيات. لكل فرضية في الدراسة: قيّمها عند α=0.05، اتخذ قرار قبول/رفض الفرضية الصفرية، اذكر قيمة P وقيمة الاختبار ودرجات الحرية وحجم الأثر وفترة الثقة، وميّز بين الدلالة الإحصائية والأهمية العملية.",
      schema:'{"items":[{"hypothesis":"نص الفرضية","testUsed":"الاختبار المستخدم","pValue":"قيمة P","testStat":"قيمة الاختبار","decision":"قبول/رفض H0","effectSize":"حجم الأثر","ci":"فترة الثقة","practicalSig":"الأهمية العملية","interpretation":"التفسير"}],"summary":"ملخص قرارات الفرضيات"}' },
    { id:"full", icon:"📚", ar:"الإطار الشامل (النتائج والاستنتاجات والتوصيات)", color:"#6d28d9",
      desc:"المراحل التسع كاملة + المناقشة + التوصيات المصنّفة",
      sys:"أنت خبير كتابة فصل النتائج والمناقشة. طبّق إطار التفسير الشامل بالمراحل: (1) التفسير الوصفي للخصائص الديموغرافية، (2) تفسير الجداول والأشكال، (3) اختبار الفرضيات واتخاذ القرار عند α=0.05، (4) التحليل القائم على الأهداف، (5) المقارنة بالأدبيات، (6) الأهمية العملية والإكلينيكية، (7) صياغة الاستنتاجات، (8) التوصيات المصنّفة (ممارسة/سياسات/تعليمية/بحوث مستقبلية)، (9) معايير الإبلاغ (P، فترات الثقة، حجم الأثر). اكتب فصلاً متكاملاً منظّماً.",
      schema:null },
  ];

  const run = async () => {
    const fcs = await Promise.all(files.map(readFile));
    const src = [text, ...fcs].join("\n").trim();
    if (!src) { alert("ارفع نتائج التحليل أو الصقها أولاً"); return; }
    setLoading(true); setResult(null); setProg(`${mode.ar}...`);
    const ctx = `${title?("الدراسة: "+title+"\n"):""}${field?("التخصص: "+field+"\n"):""}${objectives?("الأهداف:\n"+objectives+"\n"):""}${hypotheses?("الفرضيات:\n"+hypotheses+"\n"):""}\nنتائج التحليل:\n${src.slice(0,12000)}`;
    try {
      if (mode.schema) {
        const r = await asJ(`${mode.sys}\nاعمل على النتائج الفعلية فقط ولا تخترع أرقاماً. أعطِ JSON فقط:\n${mode.schema}`, ctx, 3000);
        setResult({ kind:"structured", data:r });
      } else {
        const r = await asTxt(`${mode.sys}\nاعمل على النتائج الفعلية فقط ولا تخترع أرقاماً.`, ctx, 3200);
        setResult({ kind:"text", content:r });
      }
    } catch(e){ alert("تعذّر: "+e.message); }
    finally { setLoading(false); setProg(""); }
  };

  // local AI helpers (reuse global callAI)
  async function asTxt(sys,user,mt){ return await callAI(sys,user,mt); }
  async function asJ(sys,user,mt){ const t=await callAI(sys+"\nReply ONLY valid JSON, no backticks.",user,mt); let s=t.replace(/```json|```/g,"").trim(); const a=s.indexOf("{"),b=s.lastIndexOf("}"); if(a>=0&&b>a)s=s.slice(a,b+1); return JSON.parse(s); }

  const FIELD_LABELS = {
    table:[["statInterp","📊 التفسير الإحصائي"],["sciInterp","🔬 التفسير العلمي"],["hypothesisDecision","🧪 قرار الفرضية"],["objectiveLink","🎯 ربط الهدف"],["priorComparison","📚 مقارنة بالدراسات السابقة"],["effectSize","📏 حجم الأثر"],["practicalSig","💡 الأهمية العملية"],["conclusion","✅ الاستنتاج"],["recommendation","📌 التوصية"]],
    figure:[["trend","📈 تحليل الاتجاه"],["outliers","⚠️ القيم الشاذة"],["temporal","🕐 التغيرات الزمنية"],["groupDiff","👥 الفروق بين المجموعات"],["modelQuality","🎚️ جودة النموذج"],["interpretation","💬 التفسير العام"]],
    hypotheses:[["testUsed","🧮 الاختبار"],["pValue","📉 قيمة P"],["testStat","🔢 قيمة الاختبار"],["decision","⚖️ القرار"],["effectSize","📏 حجم الأثر"],["ci","📐 فترة الثقة"],["practicalSig","💡 الأهمية العملية"],["interpretation","💬 التفسير"]],
  };

  const buildReport = () => {
    const esc=s=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    let body=`<div class="cover"><h1>${mode.icon} ${esc(mode.ar)}</h1><p><b>${esc(title)}</b></p><p>${esc(field)} | ${new Date().toLocaleDateString("ar-SA")}</p></div>`;
    if(result.kind==="text"){ body+=`<div class="pre">${esc(result.content)}</div>`; }
    else {
      const labels=FIELD_LABELS[mode.id]||[];
      (result.data.items||[]).forEach((it,i)=>{
        const name=it.tableName||it.figureName||it.hypothesis||`عنصر ${i+1}`;
        body+=`<div class="item"><h2>${esc(name)}</h2>`;
        labels.forEach(([k,l])=>{ if(it[k]) body+=`<div class="row"><b>${l}:</b> ${esc(it[k])}</div>`; });
        body+=`</div>`;
      });
      if(result.data.summary) body+=`<div class="item"><h2>الخلاصة</h2><div class="pre">${esc(result.data.summary)}</div></div>`;
    }
    return `<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>${esc(mode.ar)}</title>
<style>body{font-family:Arial;padding:40px;color:#1a2540;line-height:1.9}.cover{text-align:center;border-bottom:4px solid ${mode.color};padding-bottom:18px;margin-bottom:20px}.cover h1{color:${mode.color}}h2{color:${mode.color};font-size:15px;border-right:4px solid ${mode.color};padding-right:9px;margin-top:16px}.item{border:1px solid #e5e7eb;border-radius:8px;padding:13px;margin-bottom:12px}.row{margin:6px 0;font-size:13px}.row b{color:#1f3864}.pre{white-space:pre-wrap;font-size:13px}</style></head><body>${body}</body></html>`;
  };
  const dl=(c,m,e)=>{const b=new Blob(["\uFEFF"+c],{type:m+";charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=`${mode.ar}_${title||""}.${e}`;a.click();URL.revokeObjectURL(u);};

  return <div>
    {!mode && <div>
      <Card T={T} style={{marginBottom:14,background:`linear-gradient(135deg,${T.blue}10,transparent)`,border:`1px solid ${T.blue}44`}}>
        <h2 style={{margin:"0 0 6px",fontSize:20,fontWeight:900,color:T.blue}}>📊 من التحليل إلى التفسير العلمي</h2>
        <p style={{margin:0,fontSize:13,color:T.textS,lineHeight:1.7}}>لا يكتفي بالأرقام — بل ينتقل إلى التفسير العلمي واختبار الفرضيات والمناقشة والاستنتاجات والتوصيات المصنّفة، وفق إطار التفسير المنهجي الدولي.</p>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(245px,1fr))",gap:11}}>
        {MODES.map(m=><button key={m.id} onClick={()=>{setMode(m);setResult(null);}}
          style={{background:T.card,border:`1.5px solid ${T.border}`,borderRadius:14,padding:15,cursor:"pointer",fontFamily:"inherit",textAlign:"right",transition:"all .18s"}}
          onMouseEnter={e=>{e.currentTarget.style.borderColor=m.color;e.currentTarget.style.transform="translateY(-3px)";}}
          onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform="none";}}>
          <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:8}}>
            <div style={{width:46,height:46,borderRadius:12,background:m.color+"1a",border:`1px solid ${m.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}><EmIcon e={m.icon}/></div>
            <div style={{fontSize:14,fontWeight:800,color:T.text}}>{m.ar}</div>
          </div>
          <p style={{margin:0,fontSize:11,color:T.textD}}>{m.desc}</p>
        </button>)}
      </div>
    </div>}

    {mode && !result && !loading && <div>
      <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:16}}>
        <Btn ch="← الأنواع" onClick={()=>setMode(null)} v="ghost" size="sm" T={T}/>
        <div style={{width:44,height:44,borderRadius:12,background:mode.color+"1a",border:`1px solid ${mode.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}><EmIcon e={mode.icon}/></div>
        <h2 style={{margin:0,fontSize:17,fontWeight:900,color:T.text}}>{mode.ar}</h2>
      </div>
      <Card T={T}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:12}}>
          <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="عنوان الدراسة" style={{padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
          <input value={field} onChange={e=>setField(e.target.value)} placeholder="التخصص" style={{padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
        </div>
        <textarea value={objectives} onChange={e=>setObjectives(e.target.value)} placeholder="أهداف الدراسة (اختياري — لربط النتائج بها)" rows={2} style={{width:"100%",padding:"9px 12px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:12,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",marginBottom:10}}/>
        <textarea value={hypotheses} onChange={e=>setHypotheses(e.target.value)} placeholder="فرضيات الدراسة (اختياري)" rows={2} style={{width:"100%",padding:"9px 12px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:12,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",marginBottom:10}}/>
        <FileZone files={files} setFiles={setFiles} T={T}/>
        <textarea value={text} onChange={e=>setText(e.target.value)} placeholder="الصق نتائج التحليل الإحصائي (الجداول، مخرجات SPSS/Excel، قيم الاختبارات...)" rows={6} style={{width:"100%",padding:"11px 13px",borderRadius:10,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",margin:"12px 0"}}/>
        <Btn ch={<><EmIcon e={mode.icon}/> ابدأ {mode.ar}</>} onClick={run} disabled={!text.trim()&&!files.length} full T={T} size="lg"/>
      </Card>
    </div>}

    {loading && <Card T={T} style={{textAlign:"center",padding:36}}>
      <div style={{display:"flex",justifyContent:"center",marginBottom:12}}><Spin color={mode.color}/></div>
      <p style={{margin:0,fontSize:13,color:T.textS}}>{prog}</p>
    </Card>}

    {result && <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,flexWrap:"wrap"}}>
        <Btn ch="← جديد" onClick={()=>setResult(null)} v="ghost" size="sm" T={T}/>
        <Tag ch={mode.ar} color={mode.color}/>
        {title&&<span style={{fontSize:13,fontWeight:700,color:T.text}}>{title}</span>}
        <div style={{flex:1}}/>
        <Btn ch="📄 Word" onClick={()=>dl(buildReport(),"application/msword","doc")} v="gold" size="sm" T={T}/>
        <Btn ch="📕 PDF" onClick={()=>{const w=window.open();w.document.write(buildReport().replace("</body>","<script>window.onload=()=>window.print()<\/script></body>"));}} v="ghost" size="sm" T={T}/>
        <Btn ch="🖨️" onClick={()=>{const w=window.open();w.document.write(buildReport());w.print();}} v="ghost" size="sm" T={T}/>
      </div>

      {result.kind==="text" && <Card T={T}>
        <pre style={{margin:0,fontSize:13,color:T.text,lineHeight:1.9,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{result.content}</pre>
      </Card>}

      {result.kind==="structured" && <div>
        {(result.data.items||[]).map((it,i)=>{ const labels=FIELD_LABELS[mode.id]||[]; const name=it.tableName||it.figureName||it.hypothesis||`عنصر ${i+1}`;
          return <Card key={i} T={T} style={{marginBottom:12}}>
            <h4 style={{margin:"0 0 10px",fontSize:14,fontWeight:800,color:mode.color,borderRight:`3px solid ${mode.color}`,paddingRight:9}}>{name}</h4>
            {labels.map(([k,l])=> it[k] && <div key={k} style={{marginBottom:8,padding:"8px 11px",background:T.bgS,borderRadius:8}}>
              <span style={{fontSize:12,fontWeight:700,color:T.text}}>{l}: </span>
              <span style={{fontSize:12.5,color:T.textS,lineHeight:1.7}}>{it[k]}</span>
            </div>)}
          </Card>;
        })}
        {result.data.summary && <Card T={T} glow={mode.color}>
          <h4 style={{margin:"0 0 8px",fontSize:14,fontWeight:800,color:mode.color}}>📋 الخلاصة</h4>
          <pre style={{margin:0,fontSize:13,color:T.text,lineHeight:1.85,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{result.data.summary}</pre>
        </Card>}
      </div>}
    </div>}
  </div>;
}



// ═══ مختبر البحث العلمي المتكامل (مدمج) ═══
function ResearchLabSystem({ T }) {
  const [stage, setStage] = useState(null);
  const [field, setField] = useState("");
  const [topic, setTopic] = useState("");
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [prog, setProg] = useState("");
  const [result, setResult] = useState("");
  const fileRef = useRef();

  const STAGES = [
    { id:"ideas", icon:"💡", ar:"توليد أفكار بحثية", color:"#b45309",
      sys:"أنت موجّه بحثي خبير. اقترح أفكاراً بحثية أصيلة في المجال المحدد: لكل فكرة العنوان المقترح، المبرر، الفجوة البحثية، الأهمية، ومدى القابلية للتنفيذ. قدّم 5-7 أفكار متنوعة." },
    { id:"problem", icon:"❓", ar:"صياغة مشكلة البحث", color:"#be123c",
      sys:"أنت خبير منهجية. صُغ مشكلة بحثية محكمة من الموضوع: بيان المشكلة، أعراضها، أدلة وجودها، الفجوة البحثية، ولماذا تستحق الدراسة. صياغة أكاديمية دقيقة." },
    { id:"questions", icon:"🎯", ar:"الأسئلة والأهداف والفرضيات", color:"#0369a1",
      sys:"أنت خبير تصميم بحثي. من الموضوع/المشكلة، صُغ: الهدف العام، الأهداف الفرعية (قابلة للقياس), أسئلة البحث، والفرضيات (صفرية وبديلة) مترابطة ومتسقة." },
    { id:"litreview", icon:"📚", ar:"خطة مراجعة الأدبيات", color:"#047857",
      sys:"أنت خبير مراجعة أدبيات. ضع خطة مراجعة أدبيات منظمة: المحاور الرئيسية، الكلمات المفتاحية للبحث، قواعد البيانات المقترحة، معايير الاشتمال/الاستبعاد، وهيكل عرض الإطار النظري والدراسات السابقة." },
    { id:"framework", icon:"🏗️", ar:"الإطار النظري والمفاهيمي", color:"#6d28d9",
      sys:"أنت خبير بناء الأطر النظرية. اقترح إطاراً نظرياً ومفاهيمياً: النظريات الداعمة، المتغيرات (المستقلة/التابعة/الوسيطة)، العلاقات المفترضة، والنموذج المفاهيمي موصوفاً نصياً." },
    { id:"methodology", icon:"🔬", ar:"تصميم المنهجية", color:"#0e7490",
      sys:"أنت خبير مناهج البحث. صمّم منهجية متكاملة مناسبة للموضوع: نوع المنهج ومبرره، مجتمع الدراسة، أسلوب وحجم العينة، أدوات جمع البيانات، الصدق والثبات، إجراءات التحليل، والاعتبارات الأخلاقية." },
    { id:"proposal", icon:"📋", ar:"خطة بحث كاملة (Proposal)", color:"#1d4ed8",
      sys:"أنت خبير كتابة مقترحات بحثية. اكتب خطة بحث متكاملة: العنوان، المقدمة، المشكلة، الأهداف والأسئلة، الأهمية، حدود الدراسة، الإطار النظري المختصر، المنهجية، الجدول الزمني، والمراجع المقترحة." },
    { id:"titles", icon:"✏️", ar:"اقتراح وتحسين العناوين", color:"#7c3aed",
      sys:"أنت خبير صياغة العناوين الأكاديمية. اقترح 8-10 عناوين بحثية محكمة (دقيقة، تتضمن المتغيرات والمجتمع، ليست طويلة)، وحسّن العنوان الحالي إن وُجد، مع شرح مزايا كل عنوان." },
  ];

  const run = async () => {
    const fcs = await Promise.all(files.map(readFile));
    const src = [text, ...fcs].join("\n").trim();
    setLoading(true); setResult(""); setProg(`${stage.ar}...`);
    try {
      const r = await callAI(
        `${stage.sys}\nاكتب بالعربية بأسلوب أكاديمي منظّم. ${src?"استند للمحتوى المرفق.":""}`,
        `المجال: ${field||"عام"}\nالموضوع: ${topic||"غير محدد"}\n${src?("\nالمحتوى:\n"+src.slice(0,9000)):""}`, 2600
      );
      setResult(r);
    } catch(e){ alert("تعذّر: "+e.message); }
    finally { setLoading(false); setProg(""); }
  };

  const dl=(cnt,m,e)=>{const b=new Blob(["\uFEFF"+cnt],{type:m+";charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=`${stage.ar}_${topic||"بحث"}.${e}`;a.click();URL.revokeObjectURL(u);};
  const wordHTML=()=>`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>${stage.ar}</title><style>body{font-family:Arial;padding:40px;line-height:1.9;white-space:pre-wrap}h1{color:${stage.color}}</style></head><body><h1>${stage.icon} ${stage.ar}</h1><p><b>${topic||""}</b> | ${field||""}</p>${result.replace(/</g,"&lt;")}</body></html>`;

  return <div>
    {!stage && <div>
      <Card T={T} style={{marginBottom:14,background:`linear-gradient(135deg,${T.gold}10,transparent)`,border:`1px solid ${T.gold}44`}}>
        <h2 style={{margin:"0 0 6px",fontSize:20,fontWeight:900,color:T.gold}}>🔬 مختبر البحث العلمي</h2>
        <p style={{margin:0,fontSize:13,color:T.textS,lineHeight:1.7}}>رفيقك من الفكرة إلى الخطة الكاملة: توليد الأفكار · صياغة المشكلة · الأسئلة والأهداف والفرضيات · مراجعة الأدبيات · الإطار النظري · المنهجية · خطة البحث · العناوين.</p>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(230px,1fr))",gap:11}}>
        {STAGES.map(s=><button key={s.id} onClick={()=>{setStage(s);setResult("");}}
          style={{background:T.card,border:`1.5px solid ${T.border}`,borderRadius:14,padding:15,cursor:"pointer",fontFamily:"inherit",textAlign:"right",display:"flex",alignItems:"center",gap:11,transition:"all .18s"}}
          onMouseEnter={e=>{e.currentTarget.style.borderColor=s.color;e.currentTarget.style.transform="translateY(-2px)";}}
          onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform="none";}}>
          <div style={{width:46,height:46,borderRadius:12,background:s.color+"1a",border:`1px solid ${s.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}><EmIcon e={s.icon}/></div>
          <span style={{fontSize:13,fontWeight:700,color:T.text}}>{s.ar}</span>
        </button>)}
      </div>
    </div>}

    {stage && !result && !loading && <div>
      <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:16}}>
        <Btn ch="← المراحل" onClick={()=>setStage(null)} v="ghost" size="sm" T={T}/>
        <div style={{width:44,height:44,borderRadius:12,background:stage.color+"1a",border:`1px solid ${stage.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}><EmIcon e={stage.icon}/></div>
        <h2 style={{margin:0,fontSize:18,fontWeight:900,color:T.text}}>{stage.ar}</h2>
      </div>
      <Card T={T}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:12}}>
          <input value={field} onChange={e=>setField(e.target.value)} placeholder="المجال / التخصص" style={{padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
          <input value={topic} onChange={e=>setTopic(e.target.value)} placeholder="الموضوع / العنوان المبدئي" style={{padding:"10px 13px",borderRadius:9,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
        </div>
        <FileZone files={files} setFiles={setFiles} T={T}/>
        <textarea value={text} onChange={e=>setText(e.target.value)} placeholder="تفاصيل إضافية أو نص للاستناد إليه (اختياري)..." rows={4} style={{width:"100%",padding:"11px 13px",borderRadius:10,border:`1.5px solid ${T.border}`,background:T.bg,color:T.text,fontSize:13,fontFamily:"inherit",resize:"vertical",boxSizing:"border-box",outline:"none",margin:"12px 0"}}/>
        <Btn ch={<><EmIcon e={stage.icon}/> {stage.ar}</>} onClick={run} disabled={!field.trim()&&!topic.trim()&&!text.trim()&&!files.length} full T={T} size="lg"/>
      </Card>
    </div>}

    {loading && <Card T={T} style={{textAlign:"center",padding:36}}><div style={{display:"flex",justifyContent:"center",marginBottom:12}}><Spin color={stage.color}/></div><p style={{margin:0,fontSize:13,color:T.textS}}>{prog}</p></Card>}

    {result && <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,flexWrap:"wrap"}}>
        <Btn ch="← جديد" onClick={()=>setResult("")} v="ghost" size="sm" T={T}/>
        <Tag ch={stage.ar} color={stage.color}/>
        <div style={{flex:1}}/>
        <Btn ch="📄 Word" onClick={()=>dl(wordHTML(),"application/msword","doc")} v="gold" size="sm" T={T}/>
        <Btn ch="📋 نسخ" onClick={()=>navigator.clipboard.writeText(result)} v="ghost" size="sm" T={T}/>
        <Btn ch="🖨️" onClick={()=>{const w=window.open();w.document.write(wordHTML());w.print();}} v="ghost" size="sm" T={T}/>
      </div>
      <Card T={T}><pre style={{margin:0,fontSize:13,color:T.text,lineHeight:1.9,whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{result}</pre></Card>
    </div>}
  </div>;
}


