            {REVPERF.map(([n,cnt,sp,rate,col],i)=><div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"7px 0",borderBottom:i<3?`1px solid ${T.border}`:"none"}}><div><div style={{fontSize:12.5,fontWeight:700,color:T.text}}>{n}</div><div style={{fontSize:10,color:T.textD}}>{cnt} · {sp}</div></div><span style={{background:col+"22",color:col,borderRadius:12,padding:"2px 9px",fontSize:11,fontWeight:700}}>{rate}</span></div>)}
