// ── مصمّم المجلة العلمية الذكي ───────────────────────────────
function JournalDesignerSystem({ T }) {
  const THEMES = {
    modern:   { name:"حديث وملوّن", c1:"#6366f1", c2:"#ec4899", c3:"#06b6d4", font:"'Tajawal','Segoe UI',sans-serif", head:"#0f172a", soft:"#f1f5f9" },
    nature:   { name:"علمي رصين", c1:"#047857", c2:"#0e7490", c3:"#b45309", font:"Georgia,'Times New Roman',serif", head:"#1a2e22", soft:"#f0f7f4" },
    ieee:     { name:"تقني هندسي", c1:"#1e3a8a", c2:"#0369a1", c3:"#475569", font:"'Arial',sans-serif", head:"#0f172a", soft:"#eef2f9" },
    classic:  { name:"أكاديمي كلاسيكي", c1:"#7c2d12", c2:"#92400e", c3:"#1f2937", font:"Georgia,serif", head:"#1c1917", soft:"#faf6f0" },
  };
  const [theme, setTheme] = useState("modern");
  const [meta, setMeta] = useState({ title:"", field:"", issue:"", year:"1447هـ - 2026م", publisher:"" });
  const [content, setContent] = useState(null); // AI-generated content
  const [loading, setLoading] = useState(false);
  const [loadMsg, setLoadMsg] = useState("");
  const [tab, setTab] = useState("setup"); // setup | preview
  const TH = THEMES[theme];

  // ---- توليد محتوى المجلة بالذكاء الاصطناعي ----
  async function generate() {
    if(!meta.title.trim() || !meta.field.trim()) return;
    setLoading(true); setContent(null);
    setLoadMsg("توليد هوية المجلة والمحتوى…");
    const sys = "أنت رئيس تحرير مجلة علمية محكّمة ومصمّم خبير. تنشئ محتوى مجلة احترافياً بالعربية. ترد بصيغة JSON فقط دون أي نص إضافي أو علامات.";
    const user = `أنشئ محتوى مجلة علمية محكّمة بهذه المواصفات:
العنوان: ${meta.title}
المجال: ${meta.field}
العدد: ${meta.issue||"الأول"}
السنة: ${meta.year}
الناشر: ${meta.publisher||"غير محدد"}

أرجع JSON بهذا الشكل بالضبط:
{
 "tagline": "شعار/وصف موجز للمجلة (سطر واحد)",
 "issn": "رقم ISSN افتراضي بصيغة صحيحة",
 "editorial": "افتتاحية رئيس التحرير (150-200 كلمة، احترافية وملهمة)",
 "scope": "نطاق المجلة ومجالات النشر (3 أسطر)",
 "articles": [
   {"title":"عنوان مقال علمي واقعي في المجال","authors":"اسم باحث وجهته","pages":"1-15","abstract":"ملخص علمي موجز (40 كلمة)","keywords":["كلمة1","كلمة2","كلمة3"]},
   ... (5 مقالات متنوعة في المجال)
 ],
 "stats": {"submitted": عدد, "accepted": عدد, "rejected": عدد, "reviewers": عدد, "countries": عدد},
 "sections": ["اسم قسم 1","اسم قسم 2","اسم قسم 3","اسم قسم 4"]
}`;
    try {
      const data = await callAIJson(sys, user, 2500);
      setContent(data);
      setTab("preview");
    } catch(e) {
      setContent({ error:"تعذّر التوليد. حاول مرة أخرى." });
    }
    setLoading(false);
  }

  // ---- عناصر بصرية SVG ----
  function CoverBg({ th, w=400, h=560 }) {
    return (
      <svg width="100%" viewBox={`0 0 ${w} ${h}`} style={{position:"absolute",inset:0,zIndex:0}} preserveAspectRatio="xMidYMid slice">
        <defs>
          <linearGradient id="cg1" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor={th.c1}/><stop offset="100%" stopColor={th.c2}/>
          </linearGradient>
          <radialGradient id="cg2" cx="0.8" cy="0.2" r="0.6">
            <stop offset="0%" stopColor={th.c3} stopOpacity="0.5"/><stop offset="100%" stopColor={th.c3} stopOpacity="0"/>
          </radialGradient>
        </defs>
        <rect width={w} height={h} fill="url(#cg1)"/>
        <rect width={w} height={h} fill="url(#cg2)"/>
        <circle cx={w*0.85} cy={h*0.15} r="90" fill="#fff" opacity="0.07"/>
        <circle cx={w*0.15} cy={h*0.8} r="130" fill="#fff" opacity="0.05"/>
        {[...Array(6)].map((_,i)=>(
          <line key={i} x1={i*80} y1="0" x2={i*80+200} y2={h} stroke="#fff" strokeOpacity="0.04" strokeWidth="40"/>
        ))}
        <polygon points={`0,${h} ${w*0.5},${h*0.78} ${w},${h} ${w},${h} 0,${h}`} fill="#fff" opacity="0.06"/>
      </svg>
    );
  }

  function MiniChart({ th }) {
    const bars = [62, 88, 45, 95, 70, 80];
    return (
      <svg viewBox="0 0 220 110" style={{width:"100%",maxWidth:240}}>
        {bars.map((v,i)=>(
          <rect key={i} x={12+i*35} y={100-v} width="22" height={v} rx="3"
            fill={i%2?th.c2:th.c1} opacity={0.85}/>
        ))}
        <line x1="6" y1="100" x2="214" y2="100" stroke={th.c3} strokeWidth="1.5"/>
      </svg>
    );
  }

  function DonutStat({ th, accepted, rejected }) {
    const total = (accepted||0)+(rejected||0) || 1;
    const acc = Math.round((accepted/total)*100);
    const r=42, c=2*Math.PI*r, off=c*(1-acc/100);
    return (
      <svg viewBox="0 0 110 110" style={{width:120}}>
        <circle cx="55" cy="55" r={r} fill="none" stroke={th.soft} strokeWidth="14"/>
        <circle cx="55" cy="55" r={r} fill="none" stroke={th.c1} strokeWidth="14"
          strokeDasharray={c} strokeDashoffset={off} strokeLinecap="round" transform="rotate(-90 55 55)"/>
        <text x="55" y="60" textAnchor="middle" fontSize="20" fontWeight="700" fill={th.head}>{acc}%</text>
      </svg>
    );
  }

  // ---- بناء HTML للتصدير ----
  function buildHTML() {
    if(!content || content.error) return "";
    const a = content.articles||[];
    const st = content.stats||{};
    return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
<title>${meta.title}</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800&display=swap');
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:${TH.font};color:${TH.head};background:#fff;line-height:1.8}
.cover{height:100vh;min-height:680px;background:linear-gradient(135deg,${TH.c1},${TH.c2});color:#fff;display:flex;flex-direction:column;justify-content:center;padding:60px;position:relative;overflow:hidden}
.cover::before{content:"";position:absolute;top:-100px;right:-80px;width:300px;height:300px;border-radius:50%;background:rgba(255,255,255,.08)}
.cover::after{content:"";position:absolute;bottom:-120px;left:-60px;width:380px;height:380px;border-radius:50%;background:rgba(255,255,255,.06)}
.cover>*{position:relative;z-index:2}
.badge{display:inline-block;background:rgba(255,255,255,.2);padding:6px 18px;border-radius:30px;font-size:14px;margin-bottom:24px;backdrop-filter:blur(4px)}
.cover h1{font-size:52px;font-weight:800;margin-bottom:16px;line-height:1.2}
.tagline{font-size:20px;opacity:.92;margin-bottom:40px;max-width:600px}
.cover-meta{display:flex;gap:30px;flex-wrap:wrap;font-size:15px;opacity:.9;border-top:1px solid rgba(255,255,255,.25);padding-top:24px}
.section{max-width:900px;margin:0 auto;padding:60px 40px}
.section-title{font-size:30px;font-weight:800;color:${TH.c1};margin-bottom:8px;display:flex;align-items:center;gap:12px}
.section-title::before{content:"";width:44px;height:5px;background:${TH.c2};border-radius:3px}
.editorial{background:${TH.soft};border-right:5px solid ${TH.c1};padding:30px;border-radius:14px;font-size:17px;margin-top:20px}
.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:18px;margin-top:24px}
.stat-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:22px;text-align:center;box-shadow:0 4px 14px rgba(0,0,0,.05)}
.stat-num{font-size:36px;font-weight:800;color:${TH.c1}}
.stat-lbl{font-size:13px;color:#64748b;margin-top:4px}
.toc-item{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;padding:22px;border-radius:12px;background:#fff;border:1px solid #eef2f7;margin-bottom:14px;transition:.2s}
.toc-item:hover{box-shadow:0 6px 18px rgba(0,0,0,.08);transform:translateY(-2px)}
.art-title{font-size:18px;font-weight:700;color:${TH.head};margin-bottom:6px}
.art-authors{font-size:14px;color:${TH.c2};margin-bottom:8px;font-weight:500}
.art-abstract{font-size:14px;color:#475569;line-height:1.7}
.art-kw{margin-top:10px}
.kw{display:inline-block;background:${TH.soft};color:${TH.c1};font-size:12px;padding:3px 12px;border-radius:20px;margin:0 4px 4px 0}
.pages{flex-shrink:0;background:${TH.c1};color:#fff;font-size:13px;padding:6px 12px;border-radius:8px;font-weight:600}
.scope-box{background:linear-gradient(135deg,${TH.c1}12,${TH.c3}12);border-radius:16px;padding:30px;font-size:16px;margin-top:20px}
.footer{background:${TH.head};color:#fff;text-align:center;padding:40px;font-size:14px;opacity:.95}
.deco{height:8px;background:linear-gradient(90deg,${TH.c1},${TH.c2},${TH.c3})}
</style></head><body>
<div class="cover">
  <div class="badge">📖 مجلة علمية محكّمة · ${meta.issue||"العدد الأول"}</div>
  <h1>${meta.title}</h1>
  <div class="tagline">${content.tagline||""}</div>
  <div class="cover-meta">
    <div>📅 ${meta.year}</div>
    <div>🏛️ ${meta.publisher||""}</div>
    <div>🔖 ISSN: ${content.issn||""}</div>
    <div>🔬 ${meta.field}</div>
  </div>
</div>
<div class="deco"></div>
<div class="section">
  <div class="section-title">افتتاحية العدد</div>
  <div class="editorial">${content.editorial||""}</div>
</div>
<div class="section" style="background:${TH.soft}">
  <div class="section-title">نطاق المجلة</div>
  <div class="scope-box">${content.scope||""}</div>
  <div class="stats-grid">
    <div class="stat-card"><div class="stat-num">${st.submitted||0}</div><div class="stat-lbl">بحث مُقدَّم</div></div>
    <div class="stat-card"><div class="stat-num">${st.accepted||0}</div><div class="stat-lbl">بحث مقبول</div></div>
    <div class="stat-card"><div class="stat-num">${st.reviewers||0}</div><div class="stat-lbl">محكّم</div></div>
    <div class="stat-card"><div class="stat-num">${st.countries||0}</div><div class="stat-lbl">دولة</div></div>
  </div>
</div>
<div class="section">
  <div class="section-title">فهرس المحتويات</div>
  ${a.map(x=>`<div class="toc-item"><div><div class="art-title">${x.title}</div><div class="art-authors">${x.authors}</div><div class="art-abstract">${x.abstract||""}</div><div class="art-kw">${(x.keywords||[]).map(k=>`<span class="kw">${k}</span>`).join("")}</div></div><div class="pages">ص ${x.pages}</div></div>`).join("")}
</div>
<div class="footer">${meta.title} · ${content.issn?("ISSN "+content.issn):""} · جميع الحقوق محفوظة © ${meta.year}<br>صُمِّمت بواسطة منصة محكّم</div>
</body></html>`;
  }

  function exportHTML() {
    const html = buildHTML(); if(!html) return;
    const blob = new Blob([html], {type:"text/html;charset=utf-8"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href=url; a.download=`مجلة_${meta.title||"محكّم"}.html`; a.click();
    URL.revokeObjectURL(url);
  }
  function printPDF() {
    const html = buildHTML(); if(!html) return;
    const w = window.open("","_blank");
    if(w){ w.document.write(html); w.document.close(); setTimeout(()=>w.print(),600); }
  }

  return (
    <div style={{maxWidth:920,margin:"0 auto"}}>
      <Card T={T}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:28}}>🎨</span>
          <div>
            <div style={{fontWeight:800,fontSize:18,color:T.text}}>مصمّم المجلة العلمية الذكي</div>
            <div style={{fontSize:12,color:T.textS}}>قوالب احترافية تحاكي المجلات العالمية + توليد المحتوى والعناصر البصرية بالذكاء الاصطناعي</div>
          </div>
        </div>
      </Card>

      {/* التبويبات */}
      <div style={{display:"flex",gap:8,marginTop:12}}>
        {[["setup","⚙️ الإعداد والتصميم"],["preview","👁️ المعاينة والتصدير"]].map(([k,l])=>(
          <button key={k} onClick={()=>setTab(k)} disabled={k==="preview"&&!content}
            style={{flex:1,padding:"10px",borderRadius:10,border:`1.5px solid ${tab===k?T.gold:T.border}`,
              background:tab===k?T.gold+"18":T.card,color:tab===k?T.gold:T.text,
              fontWeight:tab===k?700:500,fontSize:13,fontFamily:"inherit",cursor:(k==="preview"&&!content)?"not-allowed":"pointer",
              opacity:(k==="preview"&&!content)?0.5:1}}>{l}</button>
        ))}
      </div>

      {tab==="setup" && (
        <>
          {/* اختيار القالب */}
          <Card T={T} style={{marginTop:12}}>
            <div style={{fontSize:13,fontWeight:700,color:T.textS,marginBottom:10}}>اختر طراز التصميم</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
              {Object.entries(THEMES).map(([k,th])=>(
                <button key={k} onClick={()=>setTheme(k)}
                  style={{padding:0,borderRadius:12,overflow:"hidden",border:`2.5px solid ${theme===k?T.gold:T.border}`,
                    cursor:"pointer",background:T.card}}>
                  <div style={{height:54,background:`linear-gradient(135deg,${th.c1},${th.c2})`,position:"relative"}}>
                    <div style={{position:"absolute",bottom:6,right:8,width:20,height:20,borderRadius:"50%",background:th.c3,opacity:.8}}/>
                  </div>
                  <div style={{padding:"8px",fontSize:12.5,fontWeight:theme===k?700:500,color:theme===k?T.gold:T.text}}>{th.name}</div>
                </button>
              ))}
            </div>
          </Card>

          {/* بيانات المجلة */}
          <Card T={T} style={{marginTop:12}}>
            <div style={{fontSize:13,fontWeight:700,color:T.textS,marginBottom:12}}>بيانات المجلة</div>
            <div style={{display:"grid",gap:10}}>
              {[["title","اسم المجلة *","مثال: المجلة العربية لعلوم البيانات"],
                ["field","المجال العلمي *","مثال: الإحصاء التطبيقي وعلوم البيانات"],
                ["issue","رقم العدد","مثال: العدد الأول - المجلد 1"],
                ["year","السنة","1447هـ - 2026م"],
                ["publisher","الناشر/الجهة","مثال: كلية الغد الدولية"]].map(([k,lbl,ph])=>(
                <div key={k}>
                  <label style={{display:"block",fontSize:12,fontWeight:600,color:T.textS,marginBottom:4}}>{lbl}</label>
                  <input value={meta[k]} onChange={e=>setMeta({...meta,[k]:e.target.value})} placeholder={ph}
                    style={{width:"100%",padding:"10px 12px",borderRadius:9,border:`1.5px solid ${T.border}`,
                      background:T.inputBg,color:T.text,fontSize:13.5,fontFamily:"inherit",boxSizing:"border-box",outline:"none"}}/>
                </div>
              ))}
            </div>
            <div style={{display:"flex",justifyContent:"flex-end",marginTop:14}}>
              <Btn ch={loading?<><Spin/> {loadMsg}</>:"🎨 توليد المجلة بالذكاء الاصطناعي"} onClick={generate}
                v="gold" disabled={loading||!meta.title.trim()||!meta.field.trim()} T={T}/>
            </div>
          </Card>

          {/* معاينة العناصر البصرية */}
          <Card T={T} style={{marginTop:12}}>
            <div style={{fontSize:13,fontWeight:700,color:T.textS,marginBottom:12}}>معاينة العناصر البصرية للطراز المختار</div>
            <div style={{display:"flex",gap:16,flexWrap:"wrap",alignItems:"center"}}>
              <div style={{position:"relative",width:120,height:168,borderRadius:10,overflow:"hidden",boxShadow:T.shadow}}>
                <CoverBg th={TH} w={120} h={168}/>
                <div style={{position:"relative",zIndex:2,padding:10,color:"#fff",height:"100%",display:"flex",flexDirection:"column",justifyContent:"flex-end"}}>
                  <div style={{fontSize:11,fontWeight:800}}>غلاف المجلة</div>
                </div>
              </div>
              <div style={{textAlign:"center"}}>
                <MiniChart th={TH}/>
                <div style={{fontSize:11,color:T.textS,marginTop:4}}>مخطط بياني</div>
              </div>
              <div style={{textAlign:"center"}}>
                <DonutStat th={TH} accepted={68} rejected={32}/>
                <div style={{fontSize:11,color:T.textS,marginTop:4}}>نسبة القبول</div>
              </div>
            </div>
          </Card>
        </>
      )}

      {tab==="preview" && content && !content.error && (
        <>
          <Card T={T} style={{marginTop:12}}>
            <div style={{display:"flex",gap:10,flexWrap:"wrap",justifyContent:"flex-end"}}>
              <Btn ch="🖨️ طباعة / PDF" v="blue" onClick={printPDF} T={T}/>
              <Btn ch="⬇️ تصدير HTML" v="gold" onClick={exportHTML} T={T}/>
            </div>
          </Card>

          {/* معاينة حية مصغّرة */}
          <Card T={T} style={{marginTop:12,padding:0,overflow:"hidden"}}>
            <div style={{position:"relative",padding:"40px 30px",background:`linear-gradient(135deg,${TH.c1},${TH.c2})`,color:"#fff",overflow:"hidden"}}>
              <CoverBg th={TH}/>
              <div style={{position:"relative",zIndex:2}}>
                <div style={{display:"inline-block",background:"rgba(255,255,255,.2)",padding:"5px 14px",borderRadius:20,fontSize:12,marginBottom:14}}>📖 مجلة علمية محكّمة · {meta.issue||"العدد الأول"}</div>
                <div style={{fontSize:30,fontWeight:800,marginBottom:8,lineHeight:1.25}}>{meta.title}</div>
                <div style={{fontSize:15,opacity:.92,marginBottom:20}}>{content.tagline}</div>
                <div style={{display:"flex",gap:18,flexWrap:"wrap",fontSize:12.5,opacity:.9,borderTop:"1px solid rgba(255,255,255,.25)",paddingTop:14}}>
                  <span>📅 {meta.year}</span><span>🔖 ISSN: {content.issn}</span><span>🔬 {meta.field}</span>
                </div>
              </div>
            </div>

            <div style={{padding:"24px"}}>
              <div style={{fontSize:18,fontWeight:800,color:TH.c1,marginBottom:10}}>✒️ افتتاحية العدد</div>
              <div style={{background:T.bgS||T.inputBg,borderRight:`4px solid ${TH.c1}`,padding:"16px 18px",borderRadius:10,fontSize:14,lineHeight:1.9,color:T.text}}>{content.editorial}</div>

              {content.stats && (
                <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(90px,1fr))",gap:10,marginTop:18}}>
                  {[["submitted","مُقدَّم"],["accepted","مقبول"],["reviewers","محكّم"],["countries","دولة"]].map(([k,l])=>(
                    <div key={k} style={{textAlign:"center",padding:"14px 8px",borderRadius:10,background:T.card,border:`1px solid ${T.border}`}}>
                      <div style={{fontSize:24,fontWeight:800,color:TH.c1}}>{content.stats[k]||0}</div>
                      <div style={{fontSize:11,color:T.textS}}>{l}</div>
                    </div>
                  ))}
                </div>
              )}

              <div style={{fontSize:18,fontWeight:800,color:TH.c1,margin:"22px 0 12px"}}>📑 فهرس المحتويات</div>
              {(content.articles||[]).map((x,i)=>(
                <div key={i} style={{display:"flex",gap:12,justifyContent:"space-between",padding:"14px",borderRadius:10,background:T.card,border:`1px solid ${T.border}`,marginBottom:10}}>
                  <div style={{flex:1}}>
                    <div style={{fontSize:14.5,fontWeight:700,color:T.text,marginBottom:4}}>{x.title}</div>
                    <div style={{fontSize:12.5,color:TH.c2,fontWeight:600,marginBottom:6}}>{x.authors}</div>
                    <div style={{fontSize:12.5,color:T.textS,lineHeight:1.7}}>{x.abstract}</div>
                    <div style={{marginTop:8}}>{(x.keywords||[]).map((k,j)=>(
                      <span key={j} style={{display:"inline-block",background:TH.soft,color:TH.c1,fontSize:11,padding:"2px 10px",borderRadius:16,margin:"0 4px 4px 0"}}>{k}</span>
                    ))}</div>
                  </div>
                  <div style={{flexShrink:0,height:"fit-content",background:TH.c1,color:"#fff",fontSize:12,padding:"5px 10px",borderRadius:7,fontWeight:600}}>ص {x.pages}</div>
                </div>
              ))}
            </div>
          </Card>
        </>
      )}

      {content?.error && (
        <Card T={T} style={{marginTop:12}}>
          <div style={{color:T.rose,fontSize:14}}>{content.error}</div>
        </Card>
      )}
    </div>
  );
}


// ── دليل الأدوات المدمج ──────────────────────────────────────
